import { useState, useEffect } from "react";

const API_BASE = "http://localhost:8000";

const css = `
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --bg: #ffffff;
    --surf: #f8fafc;
    --surf2: #f1f5f9;
    --border: #e2e8f0;
    --accent: #2563eb;
    --accent-light: #3b82f6;
    --green: #059669;
    --orange: #d97706;
    --danger: #dc2626;
    --text: #0f172a;
    --text-light: #475569;
    --muted: #64748b;
    --fh: 'Space Grotesk', sans-serif;
    --fm: 'Inter', sans-serif;
  }
  body { background: var(--bg); color: var(--text); font-family: var(--fm); min-height: 100vh; }
  .bg-grid {
    position: fixed; inset: 0; z-index: 0; pointer-events: none;
    background-image: linear-gradient(rgba(37,99,235,.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(37,99,235,.03) 1px, transparent 1px);
    background-size: 44px 44px;
  }
  .bg-glow {
    position: fixed; inset: 0; z-index: 0; pointer-events: none;
    background: radial-gradient(ellipse 60% 40% at 70% 20%, rgba(37,99,235,.02) 0%, transparent 70%),
                radial-gradient(ellipse 40% 30% at 20% 80%, rgba(5,150,105,.02) 0%, transparent 60%);
  }
  .wrap { position: relative; z-index: 1; max-width: 1280px; margin: 0 auto; padding: 0 28px 100px; }
  header { padding: 44px 0 32px; border-bottom: 1px solid var(--border); margin-bottom: 36px; display: flex; align-items: flex-end; justify-content: space-between; flex-wrap: wrap; gap: 16px; }
  .header-left { display: flex; align-items: center; gap: 18px; }
  .logo { width: 48px; height: 48px; border-radius: 12px; background: linear-gradient(135deg, var(--accent), var(--accent-light)); display: flex; align-items: center; justify-content: center; font-family: var(--fh); font-weight: 800; font-size: 18px; color: white; box-shadow: 0 4px 12px rgba(37,99,235,.25); flex-shrink: 0; }
  .header-text h1 { font-family: var(--fh); font-size: clamp(20px,3.5vw,30px); font-weight: 700; color: var(--text); }
  .header-text h1 span { color: var(--accent); }
  .header-text p { font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--muted); margin-top: 4px; }
  .badge-ver { font-size: 10px; padding: 6px 14px; border-radius: 20px; background: var(--surf); border: 1px solid var(--border); color: var(--muted); font-weight: 500; }
  .status-bar { display: flex; gap: 20px; flex-wrap: wrap; align-items: center; background: var(--surf); border: 1px solid var(--border); border-radius: 12px; padding: 12px 22px; margin-bottom: 36px; font-size: 11px; box-shadow: 0 1px 3px rgba(0,0,0,.02); }
  .s-item { display: flex; align-items: center; gap: 8px; }
  .dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
  .dot-check { background: var(--muted); }
  .dot-on  { background: var(--green);  box-shadow: 0 0 7px var(--green);  animation: blink 2s infinite; }
  .dot-off { background: var(--danger); box-shadow: 0 0 7px var(--danger); }
  @keyframes blink { 0%,100%{opacity:1} 50%{opacity:.4} }
  .s-lbl { color: var(--muted); font-weight: 500; }
  .s-val { font-weight: 600; }
  .ml-auto { margin-left: auto; }
  .tabs { display: flex; gap: 3px; margin-bottom: 32px; background: var(--surf); border: 1px solid var(--border); border-radius: 10px; padding: 4px; width: fit-content; }
  .tab { padding: 10px 26px; border-radius: 7px; border: none; background: transparent; color: var(--muted); font-family: var(--fm); font-size: 11px; font-weight: 500; letter-spacing: 1.5px; text-transform: uppercase; cursor: pointer; transition: all .18s; }
  .tab-active { background: var(--accent); color: white; font-weight: 600; }
  .tab:hover:not(.tab-active) { color: var(--text); background: white; }
  .grid2 { display: grid; grid-template-columns: 1fr 380px; gap: 24px; align-items: start; }
  @media(max-width:960px){ .grid2 { grid-template-columns: 1fr; } }
  .panel { background: white; border: 1px solid var(--border); border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0,0,0,.02), 0 2px 4px -1px rgba(0,0,0,.01); }
  .panel-head { padding: 16px 24px; border-bottom: 1px solid var(--border); background: var(--surf); display: flex; align-items: center; gap: 10px; }
  .panel-icon { color: var(--accent); font-size: 14px; }
  .panel-title { font-family: var(--fh); font-weight: 600; font-size: 13px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--text-light); }
  .panel-body { padding: 26px; }
  .sec { font-size: 10px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--accent); margin: 24px 0 14px; display: flex; align-items: center; gap: 10px; }
  .sec:first-child { margin-top: 0; }
  .sec::after { content:''; flex:1; height:1px; background: var(--border); }
  .fg2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
  .fg3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; }
  .field { display: flex; flex-direction: column; gap: 6px; }
  .field label { font-size: 10px; font-weight: 600; letter-spacing: 1.5px; text-transform: uppercase; color: var(--text-light); }
  .field input, .field select { background: var(--surf); border: 1px solid var(--border); border-radius: 8px; color: var(--text); font-family: var(--fm); font-size: 13px; font-weight: 500; padding: 10px 14px; outline: none; width: 100%; transition: border-color .18s, box-shadow .18s; }
  .field input:focus, .field select:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(37,99,235,.1); }
  .btn { width: 100%; margin-top: 24px; padding: 15px; background: var(--accent); color: white; border: none; border-radius: 10px; font-family: var(--fh); font-size: 14px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; cursor: pointer; transition: transform .18s, box-shadow .18s; }
  .btn:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 10px 25px -5px rgba(37,99,235,.4); }
  .btn:disabled { opacity:.45; cursor:not-allowed; }
  .btn-load { background: var(--surf2); color: var(--accent); border: 1px solid var(--accent); }
  .r-stack { display: flex; flex-direction: column; gap: 18px; }
  .r-card { background: white; border: 1px solid var(--border); border-radius: 16px; overflow: hidden; transition: border-color .3s, box-shadow .3s; box-shadow: 0 4px 6px -1px rgba(0,0,0,.02); }
  .r-card-on { border-color: var(--accent); box-shadow: 0 4px 12px rgba(37,99,235,.08); }
  .r-head { padding: 12px 20px; border-bottom: 1px solid var(--border); background: var(--surf); display: flex; align-items: center; justify-content: space-between; }
  .r-title { font-family: var(--fh); font-size: 10px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--text-light); }
  .r-body { padding: 22px; }
  .big { font-family: var(--fh); font-size: 58px; font-weight: 700; color: var(--accent); line-height: 1; letter-spacing: -2px; }
  .big-u { font-size: 18px; color: var(--muted); font-weight: 500; margin-left: 4px; }
  .big-s { font-size: 10px; font-weight: 500; color: var(--muted); letter-spacing: 2px; text-transform: uppercase; margin-top: 7px; }
  .cbadge { display: inline-flex; align-items: center; gap: 7px; padding: 7px 16px; border-radius: 22px; font-family: var(--fh); font-size: 14px; font-weight: 600; letter-spacing: 1px; text-transform: uppercase; }
  .cb-developed  { background: rgba(5,150,105,.08); color: var(--green); border: 1px solid rgba(5,150,105,.2); }
  .cb-developing { background: rgba(217,119,6,.08); color: var(--orange); border: 1px solid rgba(217,119,6,.2); }
  .cb-emerging   { background: rgba(37,99,235,.08); color: var(--accent); border: 1px solid rgba(37,99,235,.2); }
  .proba-list { margin-top: 16px; display: flex; flex-direction: column; gap: 12px; }
  .proba-row { display: flex; justify-content: space-between; font-size: 11px; margin-bottom: 4px; }
  .pname { color: var(--muted); font-weight: 500; }
  .bar-bg { height: 5px; background: var(--border); border-radius: 3px; overflow: hidden; }
  .bar { height: 100%; border-radius: 3px; transition: width .9s cubic-bezier(.16,1,.3,1); }
  .bar-developed  { background: var(--green); }
  .bar-developing { background: var(--orange); }
  .bar-emerging   { background: var(--accent); }
  .empty { padding: 40px 20px; text-align: center; color: var(--muted); background: var(--surf); border-radius: 12px; }
  .empty-i { font-size: 30px; opacity:.3; margin-bottom: 12px; color: var(--accent); }
  .empty-t { font-size: 12px; line-height: 1.8; font-weight: 500; }
  .loader { display: flex; gap: 7px; align-items: center; justify-content: center; padding: 24px; }
  .ld { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); animation: ld .8s infinite; }
  .ld:nth-child(2){animation-delay:.15s} .ld:nth-child(3){animation-delay:.3s}
  @keyframes ld { 0%,80%,100%{transform:scale(.5);opacity:.2} 40%{transform:scale(1);opacity:1} }
  .err { background: rgba(220,38,38,.05); border: 1px solid rgba(220,38,38,.15); border-radius: 8px; padding: 14px 18px; color: var(--danger); font-size: 12px; margin-top: 14px; display: flex; gap: 10px; line-height: 1.6; font-weight: 500; }
  .note { font-size: 10px; font-weight: 500; color: var(--text-light); margin-top: 20px; padding: 12px 16px; background: rgba(37,99,235,.02); border-left: 2px solid var(--accent); border-radius: 0 8px 8px 0; line-height: 1.8; }
  .upload-zone { border: 2px dashed var(--border); border-radius: 12px; padding: 52px 28px; text-align: center; cursor: pointer; position: relative; transition: all .2s; background: var(--surf); }
  .upload-zone:hover { border-color: var(--accent); background: white; }
  .upload-drag { border-color: var(--accent) !important; background: rgba(37,99,235,.02) !important; }
  .upload-zone input { position:absolute; inset:0; opacity:0; cursor:pointer; width:100%; height:100%; }
  .up-i { font-size: 38px; color: var(--muted); margin-bottom: 14px; }
  .up-t { font-size: 13px; color: var(--muted); line-height: 1.9; font-weight: 500; }
  .up-f { color: var(--accent); font-weight: 600; margin-top: 10px; font-size: 12px; }
  .tbl-wrap { margin-top: 24px; border: 1px solid var(--border); border-radius: 12px; overflow: auto; max-height: 420px; background: white; box-shadow: 0 1px 3px rgba(0,0,0,.02); }
  table { width: 100%; border-collapse: collapse; font-size: 11px; }
  thead th { background: var(--surf); padding: 11px 15px; text-align: left; color: var(--text-light); font-weight: 600; text-transform: uppercase; letter-spacing: 1px; position: sticky; top: 0; z-index: 1; border-bottom: 1px solid var(--border); white-space: nowrap; }
  tbody td { padding: 10px 15px; border-bottom: 1px solid var(--border); white-space: nowrap; font-weight: 500; }
  tbody tr:last-child td { border-bottom: none; }
  tbody tr:hover td { background: var(--surf); }
  .ca { color: var(--accent); font-weight: 600; }
  .cg { color: var(--green); font-weight: 600; }
  .co { color: var(--orange); font-weight: 600; }
  .about-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  @media(max-width:700px){ .about-grid { grid-template-columns: 1fr; } }
  .about-card { background: white; border: 1px solid var(--border); border-radius: 16px; padding: 24px; box-shadow: 0 4px 6px -1px rgba(0,0,0,.02); }
  .about-card h3 { font-family: var(--fh); font-size: 14px; font-weight: 700; margin-bottom: 14px; color: var(--text); }
  .about-list { list-style: none; display: flex; flex-direction: column; gap: 10px; }
  .about-list li { font-size: 12px; color: var(--text-light); display: flex; gap: 10px; line-height: 1.6; font-weight: 500; }
  .about-list li::before { content:'▸'; color: var(--accent); flex-shrink: 0; font-weight: 700; }
  .ep { display: flex; align-items: flex-start; gap: 12px; padding: 12px 0; border-bottom: 1px solid var(--border); }
  .ep:last-child { border-bottom: none; }
  .ep-m { font-size: 10px; font-weight: 700; padding: 3px 8px; border-radius: 4px; flex-shrink: 0; margin-top: 1px; }
  .get  { background: rgba(5,150,105,.08); color: var(--green); border: 1px solid rgba(5,150,105,.2); }
  .post { background: rgba(37,99,235,.08); color: var(--accent); border: 1px solid rgba(37,99,235,.2); }
  .ep-p { font-size: 13px; font-weight: 600; color: var(--text); }
  .ep-d { font-size: 11px; color: var(--muted); margin-top: 3px; line-height: 1.5; font-weight: 500; }
  .rbtn { background: white; border:1px solid var(--border); color:var(--text-light); font-family:var(--fm); font-size:10px; font-weight:500; padding:5px 12px; border-radius:6px; cursor:pointer; letter-spacing:1px; transition:all .2s; margin-left:auto; }
  .rbtn:hover { border-color:var(--accent); color:var(--accent); background:white; }
  .dlbtn { background: white; border:1px solid var(--accent); color:var(--accent); font-family:var(--fm); font-size:10px; font-weight:600; padding:7px 16px; border-radius:6px; cursor:pointer; transition:all .2s; }
  .dlbtn:hover { background: rgba(37,99,235,.02); }
  ::-webkit-scrollbar { width:6px; height:6px; }
  ::-webkit-scrollbar-track { background: var(--surf); }
  ::-webkit-scrollbar-thumb { background: var(--border); border-radius:3px; }
  ::-webkit-scrollbar-thumb:hover { background: var(--muted); }
`;

const DEFAULT = {
  Rank:50, Population:50000000, GDP_Rank:40, GDP_USD_millions:500000,
  GDP_USD_billions:500, Life_Expectancy_Male:72, Life_Expectancy_Female:76,
  GDP_per_Capita:10000, Log_Population:17.7, Log_GDP:13.1, Log_GDP_per_Capita:9.2,
  Life_Expectancy_Gender_Gap:4, Wealth_Score:0.0003, Life_Expectancy:74,
  Population_Category:"Very Large", GDP_Category:"High", Development_Level:"Emerging",
};

function bc(level) {
  if (!level) return "emerging";
  const l = level.toLowerCase();
  if (l==="developed") return "developed";
  if (l==="developing") return "developing";
  return "emerging";
}

const COLOR = { Developed:"var(--green)", Developing:"var(--orange)", Emerging:"var(--accent)" };

function Loader() {
  return <div className="loader"><div className="ld"/><div className="ld"/><div className="ld"/></div>;
}

function Empty({text}) {
  return <div className="empty"><div className="empty-i">◌</div><div className="empty-t">{text}</div></div>;
}

function NF({label, val, onChange, step="any"}) {
  return (
    <div className="field">
      <label>{label}</label>
      <input type="number" value={val} step={step} onChange={e=>onChange(parseFloat(e.target.value)||0)}/>
    </div>
  );
}

function SF({label, val, onChange, opts}) {
  return (
    <div className="field">
      <label>{label}</label>
      <select value={val} onChange={e=>onChange(e.target.value)}>
        {opts.map(o=><option key={o}>{o}</option>)}
      </select>
    </div>
  );
}

function StatusBar({health, onRefresh}) {
  const ok  = health?.status==="ok";
  const le  = health?.life_expectancy_model_loaded;
  const dl  = health?.development_level_model_loaded;
  const dc  = (b) => health ? (b?"dot-on":"dot-off") : "dot-check";
  const vc  = (b) => health ? (b?"var(--green)":"var(--danger)") : "var(--muted)";
  return (
    <div className="status-bar">
      <div className="s-item">
        <div className={`dot ${dc(ok)}`}/>
        <span className="s-lbl">API</span>
        <span className="s-val" style={{color:vc(ok)}}>{health?(ok?"ONLINE":"DEGRADED"):"CHECKING..."}</span>
      </div>
      <div className="s-item">
        <div className={`dot ${dc(le)}`}/>
        <span className="s-lbl">LIFE_EXP MODEL</span>
        <span className="s-val" style={{color:vc(le)}}>{health?(le?"LOADED":"MISSING"):"—"}</span>
      </div>
      <div className="s-item">
        <div className={`dot ${dc(dl)}`}/>
        <span className="s-lbl">DEV_LEVEL MODEL</span>
        <span className="s-val" style={{color:vc(dl)}}>{health?(dl?"LOADED":"MISSING"):"—"}</span>
      </div>
      <button className="rbtn ml-auto" onClick={onRefresh}>↺ REFRESH</button>
    </div>
  );
}

function PredictTab() {
  const [form, setForm] = useState(DEFAULT);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const set = k => v => setForm(f=>({...f,[k]:v}));

  const submit = async () => {
    setLoading(true); setError(null); setResult(null);
    try {
      const res = await fetch(`${API_BASE}/predict`,{
        method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(form)
      });
      if(!res.ok){const d=await res.json();throw new Error(d.detail||`HTTP ${res.status}`);}
      setResult(await res.json());
    } catch(e){setError(e.message);}
    finally{setLoading(false);}
  };

  const cls = result ? bc(result.development_level_prediction) : "";
  const probas = result?.development_level_probabilities || {};

  return (
    <div className="grid2">
      <div className="panel">
        <div className="panel-head"><span className="panel-icon">⬡</span><span className="panel-title">Country Parameters</span></div>
        <div className="panel-body">
          <div className="sec">Démographique & Économique</div>
          <div className="fg2">
            <NF label="World Rank"       val={form.Rank}             onChange={set("Rank")}/>
            <NF label="Population"       val={form.Population}       onChange={set("Population")}/>
            <NF label="GDP Rank"         val={form.GDP_Rank}         onChange={set("GDP_Rank")}/>
            <NF label="GDP (millions $)" val={form.GDP_USD_millions} onChange={set("GDP_USD_millions")}/>
            <NF label="GDP (billions $)" val={form.GDP_USD_billions} onChange={set("GDP_USD_billions")}/>
            <NF label="GDP per Capita"   val={form.GDP_per_Capita}   onChange={set("GDP_per_Capita")}/>
          </div>
          <div className="sec">Espérance de vie</div>
          <div className="fg2">
            <NF label="Life Exp. Male"    val={form.Life_Expectancy_Male}       onChange={set("Life_Expectancy_Male")} step="0.1"/>
            <NF label="Life Exp. Female"  val={form.Life_Expectancy_Female}     onChange={set("Life_Expectancy_Female")} step="0.1"/>
            <NF label="Gender Gap (ans)"  val={form.Life_Expectancy_Gender_Gap} onChange={set("Life_Expectancy_Gender_Gap")} step="0.1"/>
            <NF label="Life Exp. Overall" val={form.Life_Expectancy}            onChange={set("Life_Expectancy")} step="0.1"/>
          </div>
          <div className="sec">Features dérivées</div>
          <div className="fg2">
            <NF label="Log(Population)" val={form.Log_Population}    onChange={set("Log_Population")} step="0.01"/>
            <NF label="Log(GDP)"        val={form.Log_GDP}           onChange={set("Log_GDP")} step="0.01"/>
            <NF label="Log(GDP/Capita)" val={form.Log_GDP_per_Capita} onChange={set("Log_GDP_per_Capita")} step="0.01"/>
            <NF label="Wealth Score"    val={form.Wealth_Score}      onChange={set("Wealth_Score")} step="0.0001"/>
          </div>
          <div className="sec">Catégories</div>
          <div className="fg3">
            <SF label="Population Category" val={form.Population_Category} onChange={set("Population_Category")} opts={["Large","Medium","Small","Very Large"]}/>
            <SF label="GDP Category"        val={form.GDP_Category}        onChange={set("GDP_Category")}        opts={["High","Low","Medium","Very High"]}/>
            <SF label="Development Level"   val={form.Development_Level}   onChange={set("Development_Level")}   opts={["Developed","Developing","Emerging"]}/>
          </div>
          <button className={`btn ${loading?"btn-load":""}`} onClick={submit} disabled={loading}>
            {loading?"COMPUTING...":"▶ RUN PREDICTION"}
          </button>
          {error && <div className="err"><span>⚠</span><span>{error}</span></div>}
          <div className="note"><strong>💡</strong> Log(x) = ln(x). Ex: ln(50 000 000) ≈ 17.73</div>
        </div>
      </div>

      <div className="r-stack">
        <div className={`r-card ${result?"r-card-on":""}`}>
          <div className="r-head">
            <span className="r-title">Life Expectancy Prediction</span>
            {result && <span style={{fontSize:10,color:"var(--accent)",fontWeight:600}}>RÉGRESSION</span>}
          </div>
          <div className="r-body">
            {loading && <Loader/>}
            {!loading && !result && <Empty text="Soumettez le formulaire pour générer une prédiction"/>}
            {!loading && result && <>
              <div className="big">{result.life_expectancy_prediction}<span className="big-u">ans</span></div>
              <div className="big-s">Espérance de vie prédite</div>
            </>}
          </div>
        </div>

        <div className={`r-card ${result?"r-card-on":""}`}>
          <div className="r-head">
            <span className="r-title">Development Level</span>
            {result && <span style={{fontSize:10,color:"var(--accent)",fontWeight:600}}>CLASSIFICATION</span>}
          </div>
          <div className="r-body">
            {loading && <Loader/>}
            {!loading && !result && <Empty text="En attente des données"/>}
            {!loading && result && <>
              <span className={`cbadge cb-${cls}`}>● {result.development_level_prediction}</span>
              <div className="proba-list">
                {Object.entries(probas).map(([c,p])=>(
                  <div key={c}>
                    <div className="proba-row">
                      <span className="pname">{c.toUpperCase()}</span>
                      <span style={{fontSize:11,fontWeight:600,color:COLOR[c]||"var(--accent)"}}>{(p*100).toFixed(1)}%</span>
                    </div>
                    <div className="bar-bg"><div className={`bar bar-${bc(c)}`} style={{width:`${p*100}%`}}/></div>
                  </div>
                ))}
              </div>
            </>}
          </div>
        </div>
      </div>
    </div>
  );
}

function BatchTab() {
  const [file, setFile] = useState(null);
  const [drag, setDrag] = useState(false);
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState(null);
  const [error, setError] = useState(null);

  const handleFile = f => {
    if(!f) return;
    if(!f.name.endsWith(".csv")){setError("Fichier CSV requis.");return;}
    setFile(f); setError(null); setResults(null);
  };

  const submit = async () => {
    setLoading(true); setError(null);
    const fd = new FormData(); fd.append("file", file);
    try {
      const res = await fetch(`${API_BASE}/predict_batch`,{method:"POST",body:fd});
      if(!res.ok){const d=await res.json();throw new Error(d.detail||`HTTP ${res.status}`);}
      setResults(await res.json());
    } catch(e){setError(e.message);}
    finally{setLoading(false);}
  };

  const cols = results?.length
    ? ["Country","Life_Expectancy_Prediction","Development_Level_Prediction","Dev_Prob_Developed","Dev_Prob_Developing","Dev_Prob_Emerging"].filter(c=>c in results[0])
    : [];

  const download = () => {
    const ks = Object.keys(results[0]);
    const csv = [ks.join(","),...results.map(r=>ks.map(k=>JSON.stringify(r[k]??'')).join(","))].join("\n");
    const a = document.createElement("a");
    a.href = "data:text/csv;charset=utf-8,"+encodeURIComponent(csv);
    a.download = "predictions.csv"; a.click();
  };

  return (
    <div>
      <div className="panel">
        <div className="panel-head"><span className="panel-icon">⬡</span><span className="panel-title">Batch Prediction — CSV</span></div>
        <div className="panel-body">
          <div className={`upload-zone ${drag?"upload-drag":""}`}
            onDragOver={e=>{e.preventDefault();setDrag(true);}}
            onDragLeave={()=>setDrag(false)}
            onDrop={e=>{e.preventDefault();setDrag(false);handleFile(e.dataTransfer.files[0]);}}>
            <input type="file" accept=".csv" onChange={e=>handleFile(e.target.files[0])}/>
            <div className="up-i">⊕</div>
            <div className="up-t">Glissez votre CSV ici ou cliquez</div>
            {file && <div className="up-f">📄 {file.name}</div>}
          </div>
          {error && <div className="err"><span>⚠</span><span>{error}</span></div>}
          <button className={`btn ${loading?"btn-load":""}`} onClick={submit} disabled={!file||loading}>
            {loading?"PROCESSING...":"▶ RUN BATCH"}
          </button>
          <div className="note"><strong>📋 Colonnes requises :</strong> Rank, Population, GDP_Rank, GDP_USD_millions, GDP_USD_billions, Life_Expectancy, Life_Expectancy_Male, Life_Expectancy_Female, GDP_per_Capita, Log_Population, Log_GDP, Log_GDP_per_Capita, Life_Expectancy_Gender_Gap, Wealth_Score, Population_Category, GDP_Category, Development_Level</div>
        </div>
      </div>
      {results && <>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",margin:"24px 0 12px"}}>
          <div style={{fontFamily:"var(--fh)",fontSize:13,fontWeight:600}}>RÉSULTATS — <span style={{color:"var(--accent)",fontWeight:700}}>{results.length}</span> pays</div>
          <button className="dlbtn" onClick={download}>⬇ TÉLÉCHARGER CSV</button>
        </div>
        <div className="tbl-wrap">
          <table>
            <thead><tr>{cols.map(c=><th key={c}>{c.replace(/_/g," ")}</th>)}</tr></thead>
            <tbody>{results.map((r,i)=>(
              <tr key={i}>{cols.map(c=>{
                let cl="";
                if(c==="Life_Expectancy_Prediction") cl="ca";
                else if(c==="Development_Level_Prediction") cl=r[c]==="Developed"?"cg":r[c]==="Developing"?"co":"ca";
                return <td key={c} className={cl}>{r[c]??"—"}</td>;
              })}</tr>
            ))}</tbody>
          </table>
        </div>
      </>}
    </div>
  );
}

function AboutTab() {
  const eps = [
    {m:"GET",  p:"/health",        d:"Statut API et chargement des modèles"},
    {m:"POST", p:"/predict",       d:"Prédiction unique : Life Expectancy + Development Level"},
    {m:"POST", p:"/predict_batch", d:"Prédiction en lot depuis un fichier CSV"},
    {m:"GET",  p:"/docs",          d:"Swagger UI interactif"},
  ];
  return (
    <div className="about-grid">
      <div className="about-card">
        <h3>📡 Endpoints API</h3>
        {eps.map(e=>(
          <div className="ep" key={e.p}>
            <span className={`ep-m ${e.m==="GET"?"get":"post"}`}>{e.m}</span>
            <div><div className="ep-p">{e.p}</div><div className="ep-d">{e.d}</div></div>
          </div>
        ))}
      </div>
      <div className="about-card">
        <h3>🧠 Modèles ML</h3>
        <ul className="about-list">
          <li>Régression Boosting — espérance de vie en années</li>
          <li>Classification Boosting — niveau de développement</li>
          <li>Encodage one-hot drop_first=True</li>
          <li>21 features régression / 20 features classification</li>
          <li>Tracking MLflow</li>
        </ul>
      </div>
      <div className="about-card">
        <h3>🌐 Sources Wikipedia</h3>
        <ul className="about-list">
          <li>Population par pays</li>
          <li>PIB nominal (GDP) par pays</li>
          <li>Espérance de vie par pays</li>
          <li>Scraping BeautifulSoup4</li>
        </ul>
      </div>
      <div className="about-card">
        <h3>⚙️ Stack</h3>
        <ul className="about-list">
          <li><strong style={{color:"var(--accent)"}}>Backend :</strong> FastAPI, Uvicorn</li>
