export default function App() {
  const [tab, setTab] = useState("predict");
  const [health, setHealth] = useState(null);

  const checkHealth = async () => {
    setHealth(null);
    try { const r=await fetch(`${API_BASE}/health`); setHealth(await r.json()); }
    catch { setHealth({status:"error",life_expectancy_model_loaded:false,development_level_model_loaded:false}); }
  };

  useEffect(()=>{checkHealth();},[]);

  return (
    <>
      <style>{css}</style>
      <div className="bg-grid"/>
      <div className="bg-glow"/>
      <div className="wrap">
        <header>
          <div className="header-left">
            <div className="logo">ML</div>
            <div className="header-text">
              <h1>World <span>Prediction</span> API</h1>
              <p>Wikipedia Socio-Economic Pipeline</p>
            </div>
          </div>
          <div className="badge-ver">v1.0.0 · FastAPI</div>
        </header>

        <StatusBar health={health} onRefresh={checkHealth}/>

        <div className="tabs">
          {[["predict","◈ Single Predict"],["batch","◈ Batch CSV"],["about","◈ About"]].map(([id,label])=>(
            <button key={id} className={`tab ${tab===id?"tab-active":""}`} onClick={()=>setTab(id)}>{label}</button>
          ))}
        </div>

        {tab==="predict" && <PredictTab/>}
        {tab==="batch"   && <BatchTab/>}
        {tab==="about"   && <AboutTab/>}
      </div>
    </>
  );
}
